{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "Haloperidol, the highest-similarity analogue, shares a chlorophenyl and basic amine motif and has absolute oral bioavailability of 0.70 ± 0.18 in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Procainamide, a close structural analogue with a para-substituted benzamide and basic aminoethyl side chain, has an oral bioavailability of 0.85, supporting high F for the query's similar small amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "N-acetylprocainamide, another benzamide aminoethyl analogue, has an absolute oral bioavailability of 87% in humans, reinforcing that this structural class is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Sematilide, a para-substituted benzamide with a diethylaminoethyl side chain, has absolute oral bioavailability of about 46%, still clearly above the 20% threshold despite additional polar sulfonamide substitution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Indoramin shows low systemic availability around 24% with some values below 20%, but its larger lipophilic indole-piperidine structure and extensive first-pass metabolism make it a weaker transfer model for this small polar morpholine benzamide.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Loperamide has very low oral bioavailability (0.3%) due to P-gp efflux and first-pass metabolism, but its large diphenyl tertiary amide structure is too dissimilar to transfer this low-F liability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small para-chlorobenzamide with a morpholinoethyl basic side chain, closely related to procainamide, N-acetylprocainamide, and sematilide, all of which have absolute oral bioavailability above 45%, and to haloperidol with F ~60-70%. Low-F comparators are structurally more lipophilic/large and their poor bioavailability is driven by first-pass metabolism or efflux liabilities not expected for this small polar amide. Therefore F >= 20% is supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "First-pass metabolism and possible efflux liability of the morpholine/amide motif are not experimentally characterized.",
    "The effect of replacing diethylamine with morpholine and amino with chloro on absorption and clearance is inferred, not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

